Item.method_code:
/*
  指定された必要資料のやるやらを変更する
*/
Innovator inn = this.getInnovator();

// クライアントから渡されたパラメータを取得
string itemId = this.getProperty("item_id","");
string afterYryr = this.getProperty("afterYryr","");

var item = inn.newItem("h4_ReqDoc","edit");
item.setID(itemId);
item.setProperty("h4_yryr",afterYryr);
item.setAttribute("version","0");
item.setAttribute("serverEvents","0");
using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
  item = item.apply();
  if(item.isError())
  {
    return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
  }
}
return this;
